inline std::pair<::service::ni_device::pb::Update, x::errors::Error>
to_proto(const Update &value) {
    ::service::ni_device::pb::Update pb;
    const auto visit_err = std::visit(
        [&pb](const auto &v) -> x::errors::Error {
            using V = std::decay_t<decltype(v)>;
            auto [inner, err] = v.to_proto();
            if (err) return err;
            if constexpr (std::is_same_v<V, IdentityUpdate>)
                *pb.mutable_identity() = inner;
            else if constexpr (std::is_same_v<V, ConfigurationUpdate>)
                *pb.mutable_configuration() = inner;
            return x::errors::NIL;
        },
        value
    );
    return {pb, visit_err};
}

inline std::pair<Update, x::errors::Error>
update_from_proto(const ::service::ni_device::pb::Update &pb) {
    switch (pb.variant_case()) {
        case ::service::ni_device::pb::Update::kIdentity: {
            auto [v, err] = IdentityUpdate::from_proto(pb.identity());
            if (err) return {{}, err};
            return {v, x::errors::NIL};
        }
        case ::service::ni_device::pb::Update::kConfiguration: {
            auto [v, err] = ConfigurationUpdate::from_proto(pb.configuration());
            if (err) return {{}, err};
            return {v, x::errors::NIL};
        }
        default:
            return {
                {},
                x::errors::Error(x::errors::VALIDATION, "Update: no variant set")
            };
    }
}

